import csv

# Read driverStandings.csv
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    driver_standings = {row['raceId']: row for row in reader}

# Read races.csv
with open('csv/races.csv', 'r') as f:
    reader = csv.DictReader(f)
    races = {row['raceId']: row for row in reader}

# Find races where Alex Yoong (driverId=62) had round < 20
alex_races = []
for raceId, ds in driver_standings.items():
    if ds['driverId'] == '62':
        race = races.get(raceId)
        if race and int(race['round']) < 20:
            alex_races.append(race['name'])

print(f"Found {len(alex_races)} races:")
for race in alex_races:
    print(race)

